function maxLevelStretches(route: string): number {
  const n = route.length;
  const prefix = [0];
  for (const ch of route) prefix.push(prefix[prefix.length - 1] + (ch === "U" ? 1 : -1));
  const best = new Array(n + 1).fill(-Infinity);
  best[0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      if (prefix[j] === prefix[i] && best[j] + 1 > best[i]) best[i] = best[j] + 1;
    }
  }
  return best[n];
}

