class Solution:
    def maxLevelStretches(self, route: str) -> int:
        n = len(route)
        prefix = [0]
        for ch in route:
            prefix.append(prefix[-1] + (1 if ch == "U" else -1))
        best = [-math.inf] * (n + 1)
        best[0] = 0
        for i in range(1, n + 1):
            for j in range(i):
                if prefix[j] == prefix[i]:
                    best[i] = max(best[i], best[j] + 1)
        return best[n]

